"""Check full signal/cost/source aliases and bank ownership before reserve/evaluate."""
import json,hashlib,sys
from run import ROOT,R,reg,sha,put
p=json.loads((R/'plan.json').read_text());rows=json.loads((R/'batch.json').read_text());by={x['fingerprint']:x for x in rows};records=reg.read_records(ROOT/'research/automation/registry.jsonl');before='--before-reserve' in sys.argv;assert len(rows)==36 and sum(x['scope']=='native' for x in rows)==18 and p['grid']['strict_votes_required']==2 and p['grid']['slow_horizon_offsets']==[-1,0,1]
